      "section_heading": "Onboarding Basics",
      "chunk_id": "3c0ff18d-c2c6-4655-b39f-b0594d3ea77d",
      "citation_text": "Managers are responsible for assigning a buddy and scheduling the first 30-day check-in."
    },
    {
      "document_id": "OPS-001",
      "document_title": "Vendor, Travel, and Equipment Operations Policy",
      "section_heading": "Equipment Requests",
      "chunk_id": "efa74b64-3c3e-4f86-bec3-63476871ca6b",
      "citation_text": "New-hire equipment is initiated by HR Admin and fulfilled by IT Admin."
    }
